public class TagManagerKJS {
	private final Registry<?> registry;
	private final Map<ResourceLocation, TagWrapper> tags;

	public TagManagerKJS(Registry<?> registry) {
		this.registry = registry;
		this.tags = new HashMap<>();
	}

	public TagWrapper createTag(ResourceLocation id) {
		return tags.computeIfAbsent(id, k -> new TagWrapper(registry, k));
	}

	public TagWrapper getTag(ResourceLocation id) {
		return tags.get(id);
	}

	public void add(ResourceLocation tagId, ResourceLocation itemId) {
		var tag = createTag(tagId);
		tag.add(itemId);
	}

	public void remove(ResourceLocation tagId, ResourceLocation itemId) {
		var tag = tags.get(tagId);
		if (tag != null) {
			tag.remove(itemId);
		}
	}

	public void clear(ResourceLocation tagId) {
		tags.remove(tagId);
	}
}
